@Override
public PriceList getDefaultPriceList(Partner partner, int priceListTypeSelect) {
  if (partner == null) {
    return null;
  }
  partner = Beans.get(PartnerRepository.class).find(partner.getId());
  PartnerPriceList partnerPriceList = getPartnerPriceList(partner, priceListTypeSelect);
  if (partnerPriceList == null) {
    return null;
  }
  Set<PriceList> priceListSet = partnerPriceList.getPriceListSet();
  if (priceListSet == null) {
    return null;
  }
  List<PriceList> priceLists =
      priceListSet.stream()
          .filter(
              priceList ->
                  priceList.getIsActive()
                      && (priceList.getApplicationBeginDate() == null
                          || priceList
                                  .getApplicationBeginDate()
                                  .compareTo(
                                      appBaseService.getTodayDate(
                                          Optional.ofNullable(AuthUtils.getUser())
                                              .map(User::getActiveCompany)
                                              .orElse(null)))
                              <= 0)
                      && (priceList.getApplicationEndDate() == null
                          || priceList
                                  .getApplicationEndDate()
                                  .compareTo(
                                      appBaseService.getTodayDate(
                                          Optional.ofNullable(AuthUtils.getUser())
                                              .map(User::getActiveCompany)
                                              .orElse(null)))
                              >= 0))
          .collect(Collectors.toList());
  if (priceLists.size() == 1) {
    return priceLists.get(0);
  } else {
    return null;
  }
}

@Override
public PurchaseOrderLine createPurchaseOrderLine(
    PurchaseOrder purchaseOrder,
    Product product,
    String productName,
    String description,
    BigDecimal qty,
    Unit unit)
    throws AxelorException {

  PurchaseOrderLine purchaseOrderLine = new PurchaseOrderLine();
  purchaseOrderLine.setPurchaseOrder(purchaseOrder);

  purchaseOrderLine.setEstimatedReceiptDate(purchaseOrder.getEstimatedReceiptDate());

  if (product != null) {
    purchaseOrderLine.setProduct(product);
    fill(purchaseOrderLine, purchaseOrder);
  }

  if (description != null) {
    purchaseOrderLine.setDescription(description);
  }

  purchaseOrderLine.setIsOrdered(false);

  if (qty != null) {
    purchaseOrderLine.setQty(qty);
  }
  purchaseOrderLine.setSequence(sequence);
  sequence++;

  if (unit != null) {
    purchaseOrderLine.setUnit(unit);
  }

  if (productName != null) {
    purchaseOrderLine.setProductName(productName);
  }

  compute(purchaseOrderLine, purchaseOrder);

  return purchaseOrderLine;
}

@Override
@Transactional(rollbackOn = {Exception.class})
public PurchaseOrder computePurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {

  this.initPurchaseOrderLineTax(purchaseOrder);

  this._computePurchaseOrderLines(purchaseOrder);

  this._populatePurchaseOrder(purchaseOrder);

  this._computePurchaseOrder(purchaseOrder);

  return purchaseOrder;
}

@Override
public BigDecimal getQtyToOrder(
    StockLocationLine stockLocationLine, StockRules stockRules, BigDecimal minReorderQty) {
  minReorderQty = minReorderQty.max(stockRules.getReOrderQty());

  BigDecimal stockLocationLineQty =
      (stockRules.getTypeSelect() == StockRulesRepository.TYPE_CURRENT)
          ? stockLocationLine.getCurrentQty()
          : stockLocationLine.getFutureQty();

  // Get the quantity left in stock location line.
  BigDecimal qtyToOrder = stockLocationLineQty;

  // The quantity to reorder is the difference between the min/ideal
  // quantity and the quantity left in the stock location.
  BigDecimal targetQty =
      stockRules.getUseIdealQty() ? stockRules.getIdealQty() : stockRules.getMinQty();
  qtyToOrder = targetQty.subtract(qtyToOrder);

  // If the quantity we need to order is less than the reorder quantity,
  // we must choose the reorder quantity instead.
  qtyToOrder = qtyToOrder.max(minReorderQty);

  // Limit the quantity to order in order to not exceed to max quantity
  // rule.
  if (stockRules.getUseMaxQty()) {
    BigDecimal maxQtyToReorder = stockRules.getMaxQty().subtract(stockLocationLineQty);
    qtyToOrder = qtyToOrder.min(maxQtyToReorder);
  }

  return qtyToOrder;
}

@Override
public Set<Long> getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(
    StockLocation stockLocation) {
  Set<Long> resultSet = new LinkedHashSet<>();
  if (stockLocation == null) {
    return resultSet;
  }
  resultSet.add(stockLocation.getId());
  StockLocation parentStockLocation = stockLocation.getParentStockLocation();
  /* Adding to the set returns false if the value already exists, in our case this could be a good
  way to prevent an infinite loop */
  while (parentStockLocation != null && resultSet.add(parentStockLocation.getId())) {
    parentStockLocation = parentStockLocation.getParentStockLocation();
  }
  return resultSet;
}
